import io
import runpy
import sys
import unittest
from unittest.mock import patch

class HelloNameTests(unittest.TestCase):
    def run_student(self, name):
        output = io.StringIO()
        with patch('builtins.input', return_value=name):
            with patch('sys.stdout', output):
                runpy.run_path('student.py', run_name='__main__')
        return output.getvalue().strip()

    def test_chuck(self):
        self.assertEqual(self.run_student('Chuck'), 'Hello Chuck')

    def test_ada(self):
        self.assertEqual(self.run_student('Ada'), 'Hello Ada')
